240: func newAppHandler(store *Store, frontendDir string) http.Handler {
241: 	api := newAPIHandler(store)
242: 	static := http.FileServer(http.Dir(frontendDir))
243: 
244: 	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
245: 		if strings.HasPrefix(r.URL.Path, "/api/") {
246: 			api.ServeHTTP(w, r)
247: 			return
248: 		}
249: 
250: 		requestedPath := filepath.Join(frontendDir, filepath.Clean(r.URL.Path))
251: 		if r.URL.Path == "/" {
252: 			requestedPath = filepath.Join(frontendDir, "index.html")
253: 		}
254: 		if _, err := os.Stat(requestedPath); err != nil {
255: 			http.ServeFile(w, r, filepath.Join(frontendDir, "index.html"))
256: 			return
257: 		}
258: 		static.ServeHTTP(w, r)
259: 	})
260: }
261: 
262: func readID(w http.ResponseWriter, r *http.Request) (int64, bool) {
263: 	id, err := strconv.ParseInt(r.PathValue("id"), 10, 64)
264: 	if err != nil || id < 1 {
265: 		writeError(w, http.StatusBadRequest, "invalid todo id")
266: 		return 0, false
267: 	}
268: 	return id, true
269: }
270: 
271: func readJSON(w http.ResponseWriter, r *http.Request, destination any) bool {
272: 	decoder := json.NewDecoder(http.MaxBytesReader(w, r.Body, 1<<20))
273: 	decoder.DisallowUnknownFields()
274: 	if err := decoder.Decode(destination); err != nil {
275: 		writeError(w, http.StatusBadRequest, "invalid JSON body")
276: 		return false
277: 	}
278: 	return true
279: }
280: 
281: func writeJSON(w http.ResponseWriter, status int, value any) {
282: 	w.Header().Set("Content-Type", "application/json")
283: 	w.WriteHeader(status)
284: 	if err := json.NewEncoder(w).Encode(value); err != nil {
285: 		log.Printf("encode response: %v", err)
286: 	}
287: }
288: 
289: func writeError(w http.ResponseWriter, status int, message string) {
290: 	writeJSON(w, status, map[string]string{"error": message})
291: }
292: 
293: func main() {
294: 	port := flag.Int("port", 8080, "HTTP port")
295: 	frontendDir := flag.String("frontend-dir", "frontend/dist", "built frontend directory")
296: 	databasePath := flag.String("database", "data/todos.db", "SQLite database path")
297: 	flag.Parse()
298: 
299: 	if err := os.MkdirAll(filepath.Dir(*databasePath), 0o755); err != nil {
300: 		log.Fatalf("create database directory: %v", err)
301: 	}
302: 	store, err := NewStore(*databasePath)
303: 	if err != nil {
304: 		log.Fatal(err)
305: 	}
306: 	defer store.Close()
307: 
308: 	address := fmt.Sprintf(":%d", *port)
309: 	log.Printf("todo app listening on http://localhost%s", address)
310: 	if err := http.ListenAndServe(address, newAppHandler(store, *frontendDir)); err != nil {
311: 		log.Fatal(err)
312: 	}
313: }

