106:       margin: 20px 0 0;
107:       padding: 0;
108:     }
109: 
110:     li.completed .title {
111:       color: #879084;
112:       text-decoration: line-through;
113:     }
114: 
115:     .title { flex: 1; padding: 0 4px; }
116:     .empty, .loading { color: #6e786c; padding: 34px 12px; text-align: center; }
117:     .error { color: #8e2f29; margin: 12px 4px; }
118: 
119:     @media (max-width: 560px) {
120:       main { padding-top: 46px; }
121:       li { align-items: stretch; flex-wrap: wrap; }
122:       li .title { flex-basis: calc(100% - 40px); }
123:     }
124:   `;
125: 
126:   constructor() {
127:     super();
128:     this.todos = [];
129:     this.newTitle = '';
130:     this.editingId = null;
131:     this.editTitle = '';
132:     this.loading = true;
133:     this.error = '';
134:   }
135: 
136:   connectedCallback() {
137:     super.connectedCallback();
138:     this.loadTodos();
139:   }
140: 
141:   async loadTodos() {
142:     this.loading = true;
143:     this.error = '';
144:     try {
145:       this.todos = await todoAPI.list();
146:     } catch (error) {
147:       this.error = error.message;
148:     } finally {
149:       this.loading = false;
150:     }
151:   }
152: 
153:   async createTodo(event) {
154:     event.preventDefault();
155:     if (!this.newTitle.trim()) return;
156: 
157:     this.error = '';
158:     try {
159:       const todo = await todoAPI.create(this.newTitle);
160:       this.todos = [...this.todos, todo];
161:       this.newTitle = '';
162:     } catch (error) {
163:       this.error = error.message;
164:     }
165:   }
166: 
167:   startEditing(todo) {
168:     this.editingId = todo.id;
169:     this.editTitle = todo.title;
170:   }
171: 
172:   cancelEditing() {
173:     this.editingId = null;
174:     this.editTitle = '';
175:   }
176: 
177:   async saveEdit(todo) {
178:     if (!this.editTitle.trim()) return;
179:     await this.saveTodo({ ...todo, title: this.editTitle });
180:     this.cancelEditing();
181:   }
182: 
183:   async toggleTodo(todo) {
184:     await this.saveTodo({ ...todo, completed: !todo.completed });
185:   }
186: 
187:   async saveTodo(todo) {
188:     this.error = '';
189:     try {
190:       const updated = await todoAPI.update(todo);
191:       this.todos = this.todos.map((item) => item.id === updated.id ? updated : item);
192:     } catch (error) {
193:       this.error = error.message;
194:     }
195:   }
196: 
197:   renderTodo(todo) {
198:     const editing = this.editingId === todo.id;
199:     return html`
200:       <li class=${todo.completed ? 'completed' : ''}>
201:         <input
202:           type="checkbox"
203:           aria-label="Mark ${todo.title} complete"
204:           .checked=${todo.completed}
205:           @change=${() => this.toggleTodo(todo)}
206:         />
207:         ${editing
208:           ? html`
209:               <input
210:                 type="text"
211:                 aria-label="Edit todo title"
212:                 .value=${this.editTitle}
213:                 @input=${(event) => { this.editTitle = event.target.value; }}
214:               />
215:               <button @click=${() => this.saveEdit(todo)}>Save</button>
216:               <button class="secondary" @click=${this.cancelEditing}>Cancel</button>
217:             `
218:           : html`
219:               <span class="title">${todo.title}</span>
220:               <button class="secondary" @click=${() => this.startEditing(todo)}>Edit</button>
221:             `}
222:       </li>
223:     `;
224:   }
225: 
226:   render() {
227:     return html`
228:       <main>
229:         <p class="eyebrow">A tiny full-stack benchmark</p>
230:         <h1>Small wins.</h1>
231:         <p class="subtitle">Keep the next thing clear and the finished things visible.</p>
232: 
233:         <form @submit=${this.createTodo}>
234:           <input
235:             type="text"
236:             aria-label="New todo title"
237:             placeholder="What needs doing?"
238:             .value=${this.newTitle}
239:             @input=${(event) => { this.newTitle = event.target.value; }}
240:           />
241:           <button type="submit">Add todo</button>
242:         </form>
243: 
244:         ${this.error ? html`<p class="error" role="alert">${this.error}</p>` : ''}
245:         ${this.loading
246:           ? html`<p class="loading">Loading todos…</p>`
247:           : this.todos.length
248:             ? html`<ul>${this.todos.map((todo) => this.renderTodo(todo))}</ul>`
249:             : html`<p class="empty">Nothing here yet. Add one small win.</p>`}
250:       </main>
251:     `;
252:   }
253: }
254: 
255: customElements.define('todo-app', TodoApp);
